use std::{ffi::OsStr, path::Path};

use serde_json::Value as JsonValue;

use crate::support::{run, run_json};

pub(crate) fn descriptor_put(cwd: &Path) -> JsonValue {
    run_json(
        cwd,
        [
            "program",
            "module",
            "protocol-descriptor",
            "put",
            "--format",
            "json",
        ],
    )
}

pub(crate) fn descriptor_verify(cwd: &Path, cid: &str) -> JsonValue {
    run_json(
        cwd,
        [
            "program",
            "module",
            "protocol-descriptor",
            "verify",
            cid,
            "--format",
            "json",
        ],
    )
}

pub(crate) fn descriptor_verify_rejected(cwd: &Path, cid: &str) -> (JsonValue, String) {
    let output = run(
        cwd,
        [
            OsStr::new("program"),
            OsStr::new("module"),
            OsStr::new("protocol-descriptor"),
            OsStr::new("verify"),
            OsStr::new(cid),
            OsStr::new("--format"),
            OsStr::new("json"),
        ],
    );
    assert!(!output.status.success());
    let raw = String::from_utf8(output.stdout).unwrap();
    let value = serde_json::from_str(&raw).unwrap_or_else(|err| {
        panic!(
            "rejected descriptor verification must emit JSON: {err}; stdout: {raw}; stderr: {}",
            String::from_utf8_lossy(&output.stderr),
        )
    });
    (value, raw)
}

